Q: How to align data in td of a table properly A: <p>Simply invert the steps you use when you create the table contents, then the rest just &quot;falls into place&quot;. That way you'd need to do minimal changes to your existing code.</p>
<p><strong>Example</strong></p>
<p>The changed part is completely inside the function passed into the <code>.forEach</code> call. Essentially, the solution involves creating a <code>String</code> of HTML content (the <code>&lt;span&gt;</code> elements with the book's data) that can later be handled the same way the rest of the data can be used.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// Bit of data to work with
const data = {
  items: [
    {
      id: 0,
      authorname: 'J. Doe',
      books: [
        { id: 'a', booktitle: 'Book A' },
        { id: 'b', booktitle: 'Book B' }
      ]
    }
  ]
};
// The reference to the &lt;tbody&gt; element
const newTbody = document.querySelector('tbody');

data.items.forEach(user =&gt; {
  // create all the books a user/author has
  const books = user.books.reduce(
    (spans, book) =&gt; `${spans}&lt;span&gt;${book.id} : ${book.booktitle}&lt;/span&gt;`,
    ''
  );

  // create a new &lt;tr&gt;
  const row = document.createElement("tr");
  row.innerHTML = `
    &lt;td&gt;${user.id}&lt;/td&gt;
    &lt;td&gt;${user.authorname}&lt;/td&gt;
    &lt;td&gt;${books}&lt;/td&gt;`;  // &lt;---- Here, the &lt;span&gt; elements are added

  newTbody.appendChild(row);
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>/* REDUNTANT FOR SOLUTION */
span {
  display: inline-block;
  border: 0.0675em solid #888;
  padding: 0.2em 0.4em;
}
span+span {
  border-inline-start-width: 0;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;table class="table table-striped table-bordered" id="data-table"&gt;
    &lt;thead&gt;
        &lt;tr&gt;
            &lt;th&gt;ID&lt;/th&gt;
            &lt;th&gt;Author Name&lt;/th&gt;
            &lt;th&gt;Books&lt;/th&gt;
        &lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;
    &lt;/tbody&gt;
&lt;/table&gt;</code></pre>
</div>
</div>
</p>
<p><strong>EDIT</strong></p>
<p>If your JSON comes from an insecure source/a source you do not have complete control over, ensure that you don't use <code>innerHTML</code>. In that case, the code to build up the <code>&lt;table&gt;</code> becomes a bit more complex as shown below:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// Bit of data to work with
const data = {
  items: [
    {
      id: 0,
      authorname: 'J. Doe',
      books: [
        { id: 'a', booktitle: 'Book A' },
        { id: 'b', booktitle: 'Book B' }
      ]
    }
  ]
};

// The reference to the &lt;tbody&gt; element
const newTbody = document.querySelector('tbody');

// This function is used to build up the &lt;span&gt; elements for the books
const makeBooks = (fragment, book) =&gt; {
  const span = document.createElement('span');
  span.textContent = `${book.id}: ${book.booktitle}`;
  fragment.append(span);
  return fragment;
};

// This is used to generate the &lt;td&gt; elements in a row
const makeCells = (tr, cellContent) =&gt; {
  const td = document.createElement('td');
  if (cellContent instanceof DocumentFragment) {
    td.append(cellContent);
  } else {
    td.textContent = cellContent;
  }
  tr.append(td);
  return tr;
};

data.items.forEach(user =&gt; {
  // create all the books a user/author has
  const books = user.books
    .reduce(makeBooks, document.createDocumentFragment());

  // create a new &lt;tr&gt; with the cells added
  const row = [user.id, user.authorname, books]
    .reduce(makeCells, document.createElement("tr"));

  newTbody.appendChild(row);
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>/* REDUNTANT FOR SOLUTION */
span {
  display: inline-block;
  border: 0.0675em solid #888;
  padding: 0.2em 0.4em;
}
span+span {
  border-inline-start-width: 0;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;table class="table table-striped table-bordered" id="data-table"&gt;
    &lt;thead&gt;
        &lt;tr&gt;
            &lt;th&gt;ID&lt;/th&gt;
            &lt;th&gt;Author Name&lt;/th&gt;
            &lt;th&gt;Books&lt;/th&gt;
        &lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;
    &lt;/tbody&gt;
&lt;/table&gt;</code></pre>
</div>
</div>
</p>
